<?php require __DIR__.'/app/bootstrap.php';$sent=false;$error='';$searchSummary=implode(' · ',array_filter([$_GET['rooms']??'',$_GET['area']??'',$_GET['timing']??'']));$initialInterest=trim((string)($_GET['interest']??($searchSummary?'Home search: '.$searchSummary:'')));if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$phone=trim($_POST['phone']??'');$interest=trim($_POST['interest']??'');$message=trim($_POST['message']??'');if(strlen($name)<2||!$email||strlen($message)<10){$error='Please enter your name, a valid email and a little more about what you are looking for.';}else{db()->prepare('INSERT INTO inquiries(name,email,phone,interest,message) VALUES(?,?,?,?,?)')->execute([$name,$email,$phone,$interest,$message]);$sent=true;}}head('Start a conversation','Tell us about the place you are looking for and our Sri Lankan property team will be in touch.');nav(); ?>
<main class="contact-page"><section class="contact-intro"><div class="section-index">YOUR NEXT CHAPTER</div><h1>Tell us what<br><em>home means to you.</em></h1><p>A little about what you are looking for is a good place to begin.</p><div class="contact-details"><a href="mailto:<?=e(setting('email','hello@nexoridgehomes.online'))?>"><?=e(setting('email','hello@nexoridgehomes.online'))?> ↗</a><a href="tel:+94112345678"><?=e(setting('phone','+94 11 234 5678'))?></a><span><?=e(setting('address','Colombo, Sri Lanka'))?></span></div></section><section class="contact-form-wrap"><?php if($sent):?><div class="success-card"><div class="section-index">MESSAGE RECEIVED</div><h2>Thank you.<br><em>We’ll be in touch.</em></h2><p>Our team will contact you soon to continue the conversation.</p><a href="/properties" class="text-link">Explore residences ↗</a></div><?php else: if($error) echo '<div class="form-error">'.e($error).'</div>'; ?><form method="post" class="enquiry-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Your name<input name="name" autocomplete="name" required minlength="2" placeholder="How should we address you?"></label><div class="form-row"><label>Email address<input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><label>Phone number<input name="phone" type="tel" autocomplete="tel" placeholder="+94"></label></div><label>What are you looking for?<input name="interest" value="<?=e($initialInterest)?>" placeholder="Buy, sell, or a particular residence"></label><label>A little more about it<textarea name="message" required minlength="10" rows="4" placeholder="The places, spaces or details that matter to you..."></textarea></label><div class="form-consent">By sending this message, you agree to our <a href="/privacy">privacy & cookie policy</a>.</div><button class="button button-dark">Send your enquiry <span>↗</span></button></form><?php endif;?></section></main><?php end_page(); ?>
